#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
#include <cstdlib>
using namespace std;

long long solve(vector<int>& arr) {
    long long abs_sum = 0;        // 绝对值之和
    int min_abs = INT_MAX;        // 最小绝对值
    int neg_count = 0;            // 负数个数

    for (int x : arr) {
        abs_sum += abs(x);
        min_abs = min(min_abs, abs(x));
        if (x < 0) {
            neg_count++;
        }
    }

    // 偶数个负数：全部可变为非负
    if (neg_count % 2 == 0) {
        return abs_sum;
    }
    // 奇数个负数：保留一个最小绝对值为负
    else {
        return abs_sum - 2LL * min_abs;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            cin >> arr[i];
        }
        cout << solve(arr) << "\n";
    }
    return 0;
}
